package io.github.tieo.phonetix.ui

/**
 * The design tokens, as the surface page declares them.
 *
 * Generated by tools/tokens.py from docs/merge/surface.html; edit that and run it
 * again. A colour written here by hand is a colour the browser does not have, which
 * is the drift one set of tokens exists to prevent.
 *
 * Colours are ARGB, which is what Compose's Color takes. A role names what a thing is
 * for and never what colour it is, so a new theme is a new palette and nothing here
 * changes.
 */
object Tokens {

    /** Sizes, spacings and radii, which no theme changes. */
    object Scale {
        const val audioSize = 28.0f
        const val badgeHeight = 22.0f
        const val borderWidth = 1.0f
        const val breakpointPhone = 600.0f
        const val buttonHeight = 36.0f
        const val cardWidth = 360.0f
        const val diagramHeight = 72.0f
        const val diagramWidth = 96.0f
        const val fontSizeBody = 15.0f
        const val fontSizeHeadline = 22.0f
        const val fontSizeIpa = 16.0f
        const val fontSizeIpaLens = 13.0f
        const val fontSizeLabel = 11.0f
        const val fontSizeLemma = 17.0f
        const val fontSizeLens = 14.0f
        const val fontSizePage = 17.0f
        const val fontSizeSense = 14.0f
        const val fontSizeSmall = 12.0f
        const val fontSizeSymbol = 32.0f
        const val handleHeight = 4.0f
        const val handleWidth = 36.0f
        const val iconSize = 20.0f
        const val lensRing = 3.0f
        const val lensSize = 56.0f
        const val lineBody = 1.45f
        const val linePage = 1.5f
        const val markSize = 15.0f
        const val popoverWidth = 300.0f
        const val progressHeight = 6.0f
        const val radiusBar = 3.0f
        const val radiusButton = 8.0f
        const val radiusCard = 14.0f
        const val radiusChip = 999.0f
        const val radiusSymbol = 6.0f
        const val rubyInboxScale = 0.5f
        const val rubyIpaScale = 0.55f
        const val rubyScale = 0.62f
        const val skeletonHeight = 12.0f
        const val space1 = 4.0f
        const val space2 = 8.0f
        const val space3 = 12.0f
        const val space4 = 16.0f
        const val space5 = 24.0f
        const val space6 = 32.0f
        const val tierCompactMinHeight = 240.0f
        const val tierCompactMinWidth = 240.0f
        const val tierFullMinHeight = 400.0f
        const val tierFullMinWidth = 320.0f
        const val toggleHeight = 22.0f
        const val toggleWidth = 40.0f
        const val touchTarget = 44.0f
        const val weightBold = 650.0f
        const val weightMedium = 500.0f
        const val weightRegular = 400.0f
    }

    /** Which set of colours a reader has chosen. */
    enum class Theme { CLASSROOM, INK, PAPER }

    /** What each role is worth in one theme and mode. */
    data class Palette(
        val accent: Long,
        val accentBg: Long,
        val accentInk: Long,
        val border: Long,
        val chipBg: Long,
        val chipInk: Long,
        val danger: Long,
        val dangerBg: Long,
        val guess: Long,
        val guessBg: Long,
        val ink: Long,
        val inkFaint: Long,
        val inkMuted: Long,
        val ipa: Long,
        val ipaConsonant: Long,
        val ipaOther: Long,
        val ipaVowel: Long,
        val pageBg: Long,
        val rubyInk: Long,
        val rubyIpa: Long,
        val scrim: Long,
        val shadow: Long,
        val skeleton: Long,
        val surface: Long,
        val surfaceRaised: Long,
        val rubyHue: Long,
    )

    fun palette(theme: Theme, dark: Boolean): Palette = when {
        theme == Theme.CLASSROOM && !dark -> Palette(
            accent = 0xFF0F6E8CL,
            accentBg = 0xFFDFF1F6L,
            accentInk = 0xFFFFFFFFL,
            border = 0xFFDDD6C4L,
            chipBg = 0xFFEBE6D8L,
            chipInk = 0xFF3E3A33L,
            danger = 0xFFA63A2AL,
            dangerBg = 0xFFF9E6E2L,
            guess = 0xFF8A4F0CL,
            guessBg = 0xFFFBE9CFL,
            ink = 0xFF1A1A1AL,
            inkFaint = 0xFF6F6A62L,
            inkMuted = 0xFF4F4A42L,
            ipa = 0xFF1B4EA3L,
            ipaConsonant = 0xFF1B4EA3L,
            ipaOther = 0xFF5C5852L,
            ipaVowel = 0xFFB8410AL,
            pageBg = 0xFFF6F3EAL,
            rubyInk = 0xFF1B4EA3L,
            rubyIpa = 0xFF4F4A42L,
            scrim = 0x0F1E190AL,
            shadow = 0x331E190AL,
            skeleton = 0xFFE6E1D3L,
            surface = 0xFFFFFDF7L,
