            inkMuted = 0xFF1F1F1FL,
            ipa = 0xFF0028A8L,
            ipaConsonant = 0xFF0028A8L,
            ipaOther = 0xFF1F1F1FL,
            ipaVowel = 0xFF6B3400L,
            pageBg = 0xFFFFFFFFL,
            rubyInk = 0xFF0028A8L,
