            danger = 0xFFA63A2AL,
            dangerBg = 0xFFF9E6E2L,
            guess = 0xFF8A4F0CL,
            guessBg = 0xFFFBEFDCL,
            ink = 0xFF1C1B19L,
            inkFaint = 0xFF767169L,
            inkMuted = 0xFF5E5A52L,
            ipa = 0xFF2F4F70L,
            ipaConsonant = 0xFF2F4F70L,
            ipaOther = 0xFF767169L,
            ipaVowel = 0xFF8A4B12L,
            pageBg = 0xFFF3F1ECL,
            rubyInk = 0xFF2F4F70L,
            rubyIpa = 0xFF5E5A52L,
            scrim = 0x0F14120EL,
            shadow = 0x2E14120EL,
            skeleton = 0xFFE8E5DEL,
            surface = 0xFFFFFFFFL,
            surfaceRaised = 0xFFF8F7F3L,
            rubyHue = 0x00000000L,
        )
        theme == Theme.PAPER && dark -> Palette(
            accent = 0xFF7FB3DCL,
            accentBg = 0xFF223543L,
            accentInk = 0xFF10202EL,
            border = 0xFF33363DL,
            chipBg = 0xFF30333AL,
            chipInk = 0xFFD3D0C8L,
            danger = 0xFFE58A7AL,
            dangerBg = 0xFF3D2622L,
            guess = 0xFFE0A85AL,
            guessBg = 0xFF3A2D1AL,
            ink = 0xFFECEBE6L,
            inkFaint = 0xFF8E8A82L,
